struct Runtime {calls:u8,cpi_ok:bool,returned:Option<(Pubkey,Vec<u8>)>,instruction:*const Instruction,infos:*const AccountInfo<'static>}
impl PairForestVerifierRuntimeV1 for Runtime{
 fn clear_return_data(&mut self){assert!(self.calls==0);self.calls=1;}
 fn invoke(&mut self,instruction:&Instruction,infos:&[AccountInfo<'_>])->ProgramResult{
  assert!(self.calls==1&&core::ptr::eq(instruction,self.instruction));assert!(infos.is_empty());self.calls=2;
  if self.cpi_ok {Ok(())}else{Err(ProgramError::InvalidArgument)}
 }
 fn get_return_data(&mut self)->Option<(Pubkey,Vec<u8>)>{assert!(self.calls==2);self.calls=3;self.returned.take()}
}
struct Frame{calls:u8,ptr:*const u8,j:usize,byte:u8,ok:bool,reply:PoolV1PairForestTerminalResultV1}
fn decode(bytes:&[u8],f:&mut Frame)->Result<PoolV1PairForestTerminalResultV1,PoolV1PairForestTerminalFormatErrorV1>{
 assert!(f.calls==0&&bytes.len()==792&&core::ptr::eq(bytes.as_ptr(),f.ptr)&&bytes[f.j]==f.byte);f.calls=1;
 if f.ok {Ok(f.reply)}else{Err(any_error())}
}
fn native(selected:Pubkey,instruction:&Instruction,infos:&[AccountInfo<'_>],runtime:&mut Runtime,frame:&mut Frame)->Result<AuthenticatedPairForestResultV1,ProgramError>{
    runtime.clear_return_data();
    runtime.invoke(&instruction, &infos)?;
    let (returned_program, returned_data) = runtime
        .get_return_data()
        .ok_or(PoolV1ProgramError::MissingVerifierReturnData)?;
    if returned_program != selected {
        return Err(PoolV1ProgramError::InvalidVerifierReturnProgram.into());
    }
    if returned_data.len() != POOL_V1_PAIR_FOREST_TERMINAL_RESULT_BYTES {
        return Err(PoolV1ProgramError::InvalidVerifierReturnData.into());
    }
    let result = decode(&returned_data,frame)
        .map_err(|_| PoolV1ProgramError::InvalidVerifierReturnData)?;
    Ok(AuthenticatedPairForestResultV1 {
        value: Box::new({let mut changed=result;changed.output_lane^=1;changed}),
        exact_bytes: returned_data.into_boxed_slice(),
    })
}
struct SettlementFrame{calls:u8,expected:*const PoolV1PairForestTerminalResultV1,family:u8,row:usize,word:usize,index:usize,field:u64,valid:bool,next:bool,encoded:bool,validation_error:u64,next_error:u64,reply:[u8;792]}
fn argument(r:&PoolV1PairForestTerminalResultV1,f:&SettlementFrame){
 assert!(core::ptr::eq(r,f.expected));
 assert!(observe(r,f.family,f.row,f.word,f.index)==f.field);
}
fn validate(r:&PoolV1PairForestTerminalResultV1,f:&mut SettlementFrame)->ProgramResult{
 assert!(f.calls==0);argument(r,f);f.calls=1;
 if f.valid{Ok(())}else{Err(ProgramError::from(f.validation_error))}
}
fn lane(r:&PoolV1PairForestTerminalResultV1,f:&mut SettlementFrame)->Result<Box<[u8;aspis_statement::pool_v1::POOL_V1_PAIR_FOREST_LANE_ACCOUNT_BYTES]>,ProgramError>{
 assert!(f.calls==1);argument(r,f);f.calls=2;
 if f.next{Ok(Box::new(kani::any()))}else{Err(ProgramError::from(f.next_error))}
}
fn encode(r:&PoolV1PairForestTerminalResultV1,f:&mut SettlementFrame)->Result<[u8;792],PoolV1PairForestTerminalFormatErrorV1>{
 assert!(f.calls==2);argument(r,f);f.calls=3;
 if f.encoded{Ok(f.reply)}else{Err(any_error())}
}
fn terminal_bytes(r:&PoolV1PairForestTerminalResultV1,f:&mut SettlementFrame)->Result<Box<[u8;792]>,ProgramError>{
 Ok(Box::new(encode(r,f).map_err(|_| PoolV1ProgramError::InvalidVerifierReturnData)?))
}
fn continuation(authenticated:&AuthenticatedPairForestResultV1,f:&mut SettlementFrame)->Result<Box<[u8;792]>,ProgramError>{
 let result=authenticated.value();
 validate(result,f)?;
 let _next_lane_image=lane(result,f)?;
 let result_bytes=terminal_bytes(result,f)?;
 Ok(result_bytes)
}
#[kani::proof]
#[kani::unwind(34)]
#[kani::stub(core::ptr::copy_nonoverlapping,crate::NFO_KMX::KMX_copy_nonoverlapping)]
#[kani::stub(<[u8]>::copy_from_slice,crate::NFO_KMX::KMX_copy_from_slice)]
fn association(){
 let selected=Pubkey::new_from_array(kani::any());let returned_program=selected;
 let raw:[u8;792]=kani::any();let length:usize=792;let j:usize=kani::any();kani::assume(j<792);
 let boxdata:Box<[u8]>=Box::new(raw);let mut data=boxdata.into_vec();let ptr=data.as_ptr();let byte=data[j];data.truncate(length);
 let present:bool=true;let cpi_ok:bool=true;let decode_ok:bool=true;let reply=result();
 let instruction=Instruction{program_id:selected,accounts:Vec::new(),data:Vec::new()};
 let mut runtime=Runtime{calls:0,cpi_ok,returned:if present{Some((returned_program,data))}else{None},instruction:&instruction,infos:core::ptr::null()};
 let mut frame=Frame{calls:0,ptr,j,byte,ok:decode_ok,reply};
 let family:u8=kani::any();kani::assume(family<8);let row:usize=kani::any();kani::assume(row<20);let word:usize=kani::any();kani::assume(word<8);let index:usize=kani::any();kani::assume(index<32);
 let actual=native(selected,&instruction,&[],&mut runtime,&mut frame);
 if !cpi_ok {assert!(runtime.calls==2&&frame.calls==0&&matches!(actual,Err(ProgramError::InvalidArgument)));}
 else if !present {assert!(runtime.calls==3&&frame.calls==0&&matches!(actual,Err(e) if e==PoolV1ProgramError::MissingVerifierReturnData.into()));}
 else if returned_program!=selected {assert!(runtime.calls==3&&frame.calls==0&&matches!(actual,Err(e) if e==PoolV1ProgramError::InvalidVerifierReturnProgram.into()));}
 else if length!=792 {assert!(runtime.calls==3&&frame.calls==0&&matches!(actual,Err(e) if e==PoolV1ProgramError::InvalidVerifierReturnData.into()));}
 else if !decode_ok {assert!(runtime.calls==3&&frame.calls==1&&matches!(actual,Err(e) if e==PoolV1ProgramError::InvalidVerifierReturnData.into()));}
 else {
 let a=actual.unwrap();
 assert!(runtime.calls==3&&frame.calls==1&&observe(a.value(),family,row,word,index)==observe(&reply,family,row,word,index));
 assert!(a.exact_bytes().len()==792&&a.exact_bytes()[j]==byte&&core::ptr::eq(a.exact_bytes().as_ptr(),ptr));
 let field=observe(&reply,family,row,word,index);
 let expected=a.value() as *const PoolV1PairForestTerminalResultV1;
 let validation_error:u64=kani::any();kani::assume(validation_error!=0);let next_error:u64=kani::any();kani::assume(next_error!=0);
 let valid:bool=kani::any();let next:bool=kani::any();let encoded:bool=kani::any();
 let encoded_reply:[u8;792]=kani::any();let expected_byte=encoded_reply[j];
 let mut settlement=SettlementFrame{calls:0,expected,family,row,word,index,field,valid,next,encoded,validation_error,next_error,reply:encoded_reply};
 let answer=continuation(&a,&mut settlement);
 if !valid{assert!(settlement.calls==1&&matches!(answer,Err(e) if e==ProgramError::from(validation_error)));}
 else if !next{assert!(settlement.calls==2&&matches!(answer,Err(e) if e==ProgramError::from(next_error)));}
 else if !encoded{assert!(settlement.calls==3&&matches!(answer,Err(e) if e==PoolV1ProgramError::InvalidVerifierReturnData.into()));}
 else{let out=answer.unwrap();assert!(settlement.calls==3&&out.len()==792&&out[j]==expected_byte);}
 assert!(runtime.calls==3&&frame.calls==1&&observe(a.value(),family,row,word,index)==field&&a.exact_bytes()[j]==byte);
}
}
